const AutoScheduler = ({ onClose }) => {
    const { firebaseService } = useApp();
    const [dateRange, setDateRange] = useState({
        start: new Date().toISOString().split('T')[0],
        end: new Date(Date.now() + 7 * 86400000).toISOString().split('T')[0]
    });
    const [scheduling, setScheduling] = useState(false);
    const [progress, setProgress] = useState(0);

    const handleAutoSchedule = async () => {
        setScheduling(true);
        setProgress(20);

        try {
            // Call the Cloud Function for auto-scheduling
            const autoSchedule = window.firebase.functions.httpsCallable('autoSchedule');

            setProgress(40);

            const result = await autoSchedule({
                institutionId: firebaseService.currentInstitution,
                startDate: dateRange.start,
                endDate: dateRange.end,
                options: {
                    includeWeekends: false,
                    overwrite: false
                }
            });

            setProgress(80);

            if (result.data.success) {
                toast.success(`Created ${result.data.assignmentsCreated} assignments!`);
                setProgress(100);
                setTimeout(onClose, 1500);
            } else {
                throw new Error('Auto-scheduling failed');
            }
        } catch (error) {
            console.error('Auto-scheduling error:', error);
            toast.error(error.message || 'Failed to auto-schedule');
            setScheduling(false);
            setProgress(0);
        }
    };

    return (
        <div className="space-y-4">
            <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Start Date</label>
                <input
                    type="date"
                    value={dateRange.start}
                    onChange={(e) => setDateRange({ ...dateRange, start: e.target.value })}
                    className="w-full px-3 py-2 border rounded-lg"
                    disabled={scheduling}
                />
            </div>
            <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">End Date</label>
                <input
                    type="date"
                    value={dateRange.end}
                    onChange={(e) => setDateRange({ ...dateRange, end: e.target.value })}
                    className="w-full px-3 py-2 border rounded-lg"
                    disabled={scheduling}
                />
            </div>

            {scheduling && (
                <div className="space-y-2">
                    <div className="flex items-center justify-between text-sm text-gray-600">
                        <span>Scheduling in progress...</span>
                        <span>{progress}%</span>
                    </div>
                    <div className="w-full bg-gray-200 rounded-full h-2">
                        <div
                            className="bg-primary-600 h-2 rounded-full transition-all duration-300"
                            style={{ width: `${progress}%` }}
                        />
                    </div>
                </div>
            )}

            <div className="flex justify-end gap-3">
                <Button variant="secondary" onClick={onClose} disabled={scheduling}>
                    Cancel
                </Button>
                <Button onClick={handleAutoSchedule} disabled={scheduling}>
                    {scheduling ? 'Scheduling...' : 'Start Auto-Schedule'}
                </Button>
            </div>
        </div>
    );
};

// ==================== Main App Component ====================
const App = () => {
    const { user, loading } = useApp();
    const [activeView, setActiveView] = useState('dashboard');

    if (loading) {
        return (
            <div className="min-h-screen flex items-center justify-center">
                <div className="text-center">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600 mx-auto"></div>
                    <p className="mt-4 text-gray-600">Loading...</p>
                </div>
            </div>
        );
    }

    if (!user) {
        return <LoginPage />;
    }

    const navItems = [
        { id: 'dashboard', label: 'Dashboard', icon: 'layout-dashboard' },
        { id: 'schedule', label: 'Schedule', icon: 'calendar' },
        { id: 'attendings', label: 'Attendings', icon: 'users' },
        { id: 'residents', label: 'Residents', icon: 'user-check' },
        { id: 'rules', label: 'Rules', icon: 'shield-check' },
        { id: 'settings', label: 'Settings', icon: 'settings' }
    ];

    const handleSignOut = async () => {
        const { firebaseService } = useApp();
        await firebaseService.signOut();
        toast.success('Signed out successfully');
    };

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Navigation */}
            <nav className="bg-white shadow-sm border-b border-gray-200">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                    <div className="flex justify-between h-16">
                        <div className="flex items-center">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-primary-100 rounded-lg">
                                    <Icon name="calendar-days" size={24} className="text-primary-600" />
                                </div>
                                <div>
                                    <h1 className="text-lg font-bold text-gray-900">Clinic Scheduler Pro</h1>
                                    <p className="text-xs text-gray-500">Firebase Edition</p>
                                </div>
                            </div>

                            <div className="hidden md:flex ml-10 space-x-1">
                                {navItems.map(item => (
                                    <button
                                        key={item.id}
                                        onClick={() => setActiveView(item.id)}
                                        className={`
                                            px-3 py-2 rounded-lg text-sm font-medium flex items-center gap-2 transition-all
                                            ${activeView === item.id
                                                ? 'bg-primary-50 text-primary-700'
                                                : 'text-gray-600 hover:bg-gray-50'
                                            }
                                        `}
                                    >
                                        <Icon name={item.icon} size={16} />
                                        {item.label}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <div className="flex items-center gap-4">
                            <div className="flex items-center gap-2 px-3 py-1 bg-green-100 rounded-lg">
                                <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
                                <span className="text-sm text-green-700 font-medium">Live</span>
                            </div>

                            <div className="flex items-center gap-2">
                                <div className="text-right">
                                    <p className="text-sm font-medium text-gray-900">{user.name || user.email}</p>
                                    <button
                                        onClick={handleSignOut}
                                        className="text-xs text-gray-500 hover:text-gray-700"
                                    >
                                        Sign Out
                                    </button>
                                </div>
                                <div className="w-8 h-8 bg-primary-100 rounded-full flex items-center justify-center">
                                    <Icon name="user" size={16} className="text-primary-600" />
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </nav>

            {/* Main Content */}
            <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
                {activeView === 'dashboard' && <Dashboard />}
                {activeView === 'schedule' && <ScheduleCalendar />}
                {activeView === 'attendings' && <AttendingsList />}
                {activeView === 'residents' && <ResidentsList />}
                {activeView === 'rules' && <RulesList />}
                {activeView === 'settings' && <SettingsView />}
            </main>

            <Toaster
                position="bottom-right"
                toastOptions={{
                    className: 'font-medium',
                    duration: 3000,
                    style: {
                        background: '#fff',
                        color: '#363636',
                    },
                }}
            />
        </div>
    );
};

// ==================== Root Component ====================
const Root = () => {
    return (
        <ToastProvider>
            <AppProvider>
                <App />
            </AppProvider>
        </ToastProvider>
    );
};

// Render the app
ReactDOM.createRoot(document.getElementById('root')).render(<Root />);
